mapper.select:
SELECT s.student_id AS studentId, s.student_name AS studentName, sc.han_fee AS hanFee, sc.book_fee AS bookFee, sc.han_material_fee AS hanMaterialFee, sc.book_material_fee AS bookMaterialFee, hu.user_name AS hanTeacher, bu.user_name AS bookTeacher, (ISNULL(sc.han_fee, 0) + ISNULL(sc.book_fee, 0) + ISNULL(sc.han_material_fee, 0) + ISNULL(sc.book_material_fee, 0)) AS totalPrice, (ISNULL(sc.han_fee, 0) + ISNULL(sc.book_fee, 0)) AS totalFee, (ISNULL(sc.han_material_fee, 0) + ISNULL(sc.book_material_fee, 0)) AS totalMaterialFee, (p.parent_tel_first + p.parent_tel_middle + p.parent_tel_last) AS parentPhone, pay.edu_status AS eduStatus, pay.material_status AS materialStatus, STUFF(( SELECT ', ' + c.class_name FROM erp_time_table_assign ta JOIN erp_time_table t ON ta.time_table_key = t.time_table_key JOIN erp_class_code c ON c.class_key = CASE WHEN t.class_key = 'COM' THEN ta.class_key ELSE t.class_key END WHERE ta.student_id = s.student_id AND c.class_type IN (1, 2) AND t.yy = #{year} AND t.mm = #{month}
AND t.user_code = #{userCode}
ORDER BY c.class_type ASC FOR XML PATH('') ), 1, 2, '') AS subject FROM erp_student s JOIN erp_student_class sc on s.student_id = sc.student_id JOIN erp_parent p ON s.student_id = p.student_id LEFT JOIN erp_user hu ON sc.han_user_code = hu.user_code LEFT JOIN erp_user bu ON sc.book_user_code = bu.user_code LEFT JOIN (select student_id, MAX(edu_status) AS edu_status, MAX(material_status) AS material_status from erp_payment WHERE yy = #{year} AND mm = #{month} group by student_id) pay ON s.student_id = pay.student_id WHERE EXISTS ( SELECT 1 FROM erp_time_table_assign ta JOIN erp_time_table t ON ta.time_table_key = t.time_table_key WHERE ta.student_id = s.student_id
AND t.user_code = #{userCode}
) AND sc.yy = #{year} AND sc.mm = #{month}

SELECT fee
FROM ERP_CLASS_FEE_MAP
WHERE class_key = #{classKey}
  AND center_code = #{centerCode}

update.foreach:
UPDATE erp_class_fee_map
SET fee = #{item.fee}
WHERE class_key = #{item.classKey}
AND center_code = #{item.centerCode}

mapper.update:
UPDATE ERP_PAYMENT
SET edu_status      = CASE WHEN edu_status IS NOT NULL THEN 'approved' ELSE edu_status END,
    material_status = CASE WHEN material_status IS NOT NULL THEN 'approved' ELSE material_status END,
    approved_date   = #{approvedAt}
WHERE bill_id = #{billId};

mapper.select:
SELECT s.student_id AS studentId, (p.yy + '-' + p.mm) AS classDate, s.student_name AS studentName, STUFF((SELECT ', ' + sub.class_name FROM (SELECT DISTINCT cc2.class_name, cc2.class_type FROM erp_time_table_assign ta2 JOIN erp_time_table t2 ON ta2.time_table_key = t2.time_table_key JOIN erp_class_code cc2 ON cc2.class_key = CASE WHEN t2.class_key = 'COM' THEN ta2.class_key ELSE t2.class_key END WHERE ta2.student_id = p.student_id AND t2.yy = p.yy AND t2.mm = p.mm) AS sub ORDER BY sub.class_type FOR XML PATH (''), TYPE ).value('.', 'NVARCHAR(MAX)'), 1, 2, '') AS subject, hu.user_name AS hanTeacher, bu.user_name AS bookTeacher, p.bill_id AS billId, p.product_name AS billType, p.approved_date AS approvedDate, p.amount AS amount, COALESCE(p.edu_status, p.material_status) AS status FROM erp_payment p JOIN erp_student s ON p.student_id = s.student_id JOIN erp_student_class sc ON s.student_id = sc.student_id AND p.yy = sc.yy AND p.mm = sc.mm LEFT JOIN erp_user hu ON sc.han_user_code = hu.user_code LEFT JOIN erp_user bu ON sc.book_user_code = bu.user_code
p.student_id = #{studentId}
ORDER BY p.created_at DESC;

SELECT p.student_id AS studentId, s.student_name AS studentName, p.bill_id AS billId, p.amount AS amount, COALESCE(p.edu_status, p.material_status) AS status FROM erp_payment p JOIN erp_student s ON p.student_id = s.student_id WHERE p.student_id IN
#{id}
AND COALESCE(p.edu_status, p.material_status) = 'approved' AND p.yy = #{year} AND p.mm = #{month}

SELECT TOP ${count} * FROM (select p.bill_id AS billId, (p.yy + '-' + p.mm) AS inym, 'S' AS gb, p.approved_date AS indate, p.han_amount AS inmoney, CASE WHEN p.product_name = '교육비' THEN 'S' WHEN p.product_name = '교재비' THEN 'B' ELSE null END AS gubun, p.created_at from erp_payment p WHERE p.han_amount IS NOT NULL AND p.student_id = #{studentId} AND P.approved_date IS NOT NULL
UNION ALL
select p.bill_id AS billId, (p.yy + '-' + p.mm) AS inym, 'I' AS gb, p.approved_date AS indate, p.book_amount AS inmoney, CASE WHEN p.product_name = '교육비' THEN 'S' WHEN p.product_name = '교재비' THEN 'B' ELSE null END AS gubun, p.created_at from erp_payment p WHERE p.book_amount IS NOT NULL AND p.student_id = #{studentId}) AS combined AND P.approved_date IS NOT NULL ORDER BY combined.billId ASC;
